function N({registerIndicator:m,sourceValues:y,nulls:b}){m({id:"oa-parzen",name:"Parzen Window Moving Average (PARZEN)",category:"Trends FIR",placement:"onchart",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"period",type:"number",label:"Period",default:14,min:2,max:5e3,step:1}],plots:[{key:"parzen",type:"line",title:"PARZEN",style:{color:"#ffeb3b",lineWidth:2}}],calc(f,p){const n=Math.max(2,Math.floor(Number(p.period)||14)),l=y(f,p.source??"close"),d=f.length,i=(n-1)/2,a=new Array(n).fill(0);let s=0;for(let e=0;e<n;e++){const u=i>0?(e-i)/i:0,t=Math.abs(u);let o=0;if(t<=.5)o=1-6*t*t+6*t*t*t;else if(t<=1){const r=1-t;o=2*r*r*r}a[e]=o,s+=o}if(s>0)for(let e=0;e<n;e++)a[e]=a[e]/s;const c=new Array(d).fill(NaN);for(let e=0;e<d;e++){const u=Number.isFinite(l[e])?l[e]:0;if(e+1<n){c[e]=u;continue}let t=0;for(let o=0;o<n;o++){const r=e-n+1+o,h=Number.isFinite(l[r])?l[r]:0;t+=h*a[o]}c[e]=t}return{parzen:b(c)}}})}export{N as default};
